import { describe, expect, test } from "vitest";
import { bundlePages } from "./bundle.mjs";

const notice =
  "<!-- Do not edit this file. It is automatically generated by API Documenter. -->\n\n";

describe("bundlePages", () => {
  test("default", () => {
    const bundled = bundlePages({
      "index.md": `${notice}[Home](./index.md)\n\n## API Reference\n\n[@docs/a](./a.md)\n`,
      "a.md": `${notice}[Home](./index.md) &gt; [@docs/a](./a.md)\n\n## a package\n\n[Foo](./a.foo.md)\n`,
      "a.foo.md": `${notice}[Home](./index.md) &gt; [@docs/a](./a.md) &gt; [Foo](./a.foo.md)\n\n## Foo class\n\nSee [bar](./a.foo.bar.md), [Baz](./b.baz.md) and [@docs/b](./b.md).\n`,
      "a.foo.bar.md": `${notice}\n## Foo.bar property\n`,
      "b.md": `${notice}\n## b package\n`,
      "b.baz.md": `${notice}\n## Baz class\n`,
    });
    expect(Object.keys(bundled).sort()).toEqual(["README.md", "a.md", "b.md"]);
    expect(bundled["README.md"]).toBe(
      `${notice}<a name="index"></a>\n\n## API Reference\n\n[@docs/a](./a.md)\n`,
    );
    expect(bundled["a.md"]).toBe(
      [
        `${notice}<a name="a"></a>\n\n## a package\n\n[Foo](#a.foo)`,
        '<a name="a.foo"></a>\n\n## Foo class\n\nSee [bar](#a.foo.bar), [Baz](./b.md#b.baz) and [@docs/b](./b.md).',
        '<a name="a.foo.bar"></a>\n\n## Foo.bar property\n',
      ].join("\n\n"),
    );
  });

  test("behavior: the package page precedes its members regardless of sort order", () => {
    const bundled = bundlePages({
      "a.md": "## a package\n",
      "a.aaa.md": "## aaa\n",
    });
    expect(bundled["a.md"].indexOf("## a package")).toBeLessThan(
      bundled["a.md"].indexOf("## aaa"),
    );
  });
});
